    {banner = 4059426536, {7, 1.0}, {1, 0.5}, {2, 0.2}, {3, 0.05}, {8, 0.075}}, -- RAIN DOWN FROM ABOVE
    {banner = 2594389917, {9, 0.6}, {1, 0.5}, {2, 0.2}, {3, 0.05}, {8, 0.075}}, -- OVERWHELMING FIREPOWER
